179	/// Effective memory settings: `[memory]` from `leviathan.toml`, then flags.
180	#[derive(Debug, Clone)]
181	pub struct Settings {
182	    pub namespace: String,
183	    pub read: Vec<String>,
184	    pub budget: usize,
185	    pub briefing_budget: usize,
186	    pub max_chars: usize,
187	    pub pin: Vec<String>,
188	    half_life: BTreeMap<Kind, f64>,
189	}
190	
191	impl Settings {
192	    pub fn from_config(cfg: &MemoryConfig) -> Self {
193	        let half_life = Kind::ALL
194	            .into_iter()
195	            .map(|k| {
196	                let days = cfg
197	                    .half_life
198	                    .iter()
199	                    .find(|(name, _)| Kind::parse(name) == Some(k))
200	                    .map_or(k.default_half_life(), |(_, d)| *d);
201	                (k, days)
202	            })
203	            .collect();
204	        let namespace = cfg.namespace.trim().to_lowercase();
205	        let read = if cfg.read.is_empty() {
206	            vec![namespace.clone()]
207	        } else {
208	            cfg.read.iter().map(|n| n.trim().to_lowercase()).collect()
209	        };
210	        Self {
211	            namespace,
212	            read,
213	            budget: cfg.budget,
214	            briefing_budget: cfg.briefing_budget,
215	            max_chars: cfg.max_chars,
216	            pin: cfg.pin.clone(),
217	            half_life,
218	        }
219	    }
220	
221	    pub fn half_life(&self, kind: Kind) -> f64 {
222	        self.half_life.get(&kind).copied().unwrap_or(0.0)
223	    }
